diff --git a/containments/desktop/package/contents/ui/FolderItemToolTip.qml b/containments/desktop/package/contents/ui/FolderItemToolTip.qml
new file mode 100644
index 0000000000..5d8928a704
--- /dev/null
+++ b/containments/desktop/package/contents/ui/FolderItemToolTip.qml
@@ -0,0 +1,107 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+import QtQuick
+import QtQuick.Layouts
+import QtQuick.Window
+
+import org.kde.plasma.components as PlasmaComponents
+import org.kde.kirigami as Kirigami
+
+import org.kde.private.desktopcontainment.folder as Folder
+
+Item {
+    id: toolTip
+
+    property string name
+    property var icon
+
+    readonly property int maximumPreviewSize: Kirigami.Units.iconSizes.enormous * 2
+
+    function load(model: Folder.FolderModel, row: int, name: string, icon: var): void {
+        toolTip.name = name;
+        toolTip.icon = icon;
+        toolTipData.load(model, row, maximumPreviewSize, Screen.devicePixelRatio);
+    }
+
+    implicitWidth: mainLayout.implicitWidth + Kirigami.Units.largeSpacing * 2
+    implicitHeight: mainLayout.implicitHeight + Kirigami.Units.largeSpacing * 2
+
+    LayoutMirroring.enabled: Application.layoutDirection === Qt.RightToLeft
+    LayoutMirroring.childrenInherit: true
+
+    Kirigami.Theme.colorSet: Kirigami.Theme.Window
+    Kirigami.Theme.inherit: false
+
+    Folder.ToolTipData {
+        id: toolTipData
+    }
+
+    RowLayout {
+        id: mainLayout
+        anchors.centerIn: parent
+
+        spacing: Kirigami.Units.gridUnit
+
+        Kirigami.Icon {
+            readonly property bool hasPreview: toolTipData.previewSize.width > 0
+
+            Layout.alignment: Qt.AlignTop
+            Layout.preferredWidth: hasPreview ? toolTipData.previewSize.width : Kirigami.Units.iconSizes.enormous
+            Layout.preferredHeight: hasPreview ? toolTipData.previewSize.height : Kirigami.Units.iconSizes.enormous
+
+            animated: false
+            roundToIconSize: false
+            source: hasPreview ? toolTipData.preview : toolTip.icon
+        }
+
+        ColumnLayout {
+            Layout.alignment: Qt.AlignTop
+            Layout.maximumWidth: Kirigami.Units.gridUnit * 20
+
+            spacing: Kirigami.Units.smallSpacing
+
+            Kirigami.Heading {
+                Layout.fillWidth: true
+                level: 3
+                wrapMode: Text.Wrap
+                textFormat: Text.PlainText
+                text: toolTip.name
+            }
+
+            GridLayout {
+                Layout.fillWidth: true
+                columns: 2
+                columnSpacing: Kirigami.Units.smallSpacing
+                rowSpacing: 0
+
+                Repeater {
+                    model: {
+                        const labelsAndValues = [];
+                        for (const detail of toolTipData.details) {
+                            labelsAndValues.push(detail.label, detail.value);
+                        }
+                        return labelsAndValues;
+                    }
+
+                    PlasmaComponents.Label {
+                        required property int index
+                        required property string modelData
+
+                        readonly property bool isLabel: index % 2 === 0
+
+                        Layout.alignment: isLabel ? Qt.AlignRight | Qt.AlignTop : Qt.AlignLeft | Qt.AlignTop
+                        Layout.fillWidth: !isLabel
+                        wrapMode: isLabel ? Text.NoWrap : Text.Wrap
+                        textFormat: Text.PlainText
+                        opacity: isLabel ? 0.75 : 1
+                        text: modelData
+                    }
+                }
+            }
+        }
+    }
+}
