@@ -0,0 +1,152 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "tooltipdata.h"
+
+#include <QDir>
+#include <QPixmap>
+
+#include <KFormat>
+#include <KIO/PreviewJob>
+#include <KLocalizedString>
+
+#ifdef HAVE_BALOO
+#include <Baloo/File>
+#include <KFileMetaData/PropertyInfo>
+#endif
+
+ToolTipData::ToolTipData(QObject *parent)
+    : QObject(parent)
+{
+}
+
+ToolTipData::~ToolTipData()
+{
+    if (m_previewJob) {
+        m_previewJob->kill();
+    }
+}
+
+QImage ToolTipData::preview() const
+{
+    return m_preview;
+}
+
+QSizeF ToolTipData::previewSize() const
+{
+    return m_preview.deviceIndependentSize();
+}
+
+QVariantList ToolTipData::details() const
+{
+    return m_details;
+}
+
+void ToolTipData::load(FolderModel *model, int row, int maximumPreviewSize, qreal devicePixelRatio)
+{
+    if (m_previewJob) {
+        m_previewJob->kill();
+    }
+
+    const KFileItem item = model ? model->itemForIndex(model->index(row, 0)) : KFileItem();
+    m_preview = QImage();
+    m_details.clear();
+    Q_EMIT previewChanged();
+
+    if (item.isNull()) {
+        Q_EMIT detailsChanged();
+        return;
+    }
+
+    const KFormat format;
+
+    addDetail(i18nc("@label file type", "Type:"), item.mimeComment());
+
+    if (item.isDir()) {
+        if (item.isLocalFile() && !item.isSlow()) {
+            const int count = QDir(item.localPath()).entryList(QDir::AllEntries | QDir::NoDotAndDotDot).count();
+            addDetail(i18nc("@label file size", "Size:"), i18ncp("@item:intable", "%1 item", "%1 items", count));
+        }
+    } else {
+        addDetail(i18nc("@label file size", "Size:"), format.formatByteSize(item.size()));
+    }
+
+    const QDateTime modified = item.time(KFileItem::ModificationTime);
+    if (modified.isValid()) {
+        addDetail(i18nc("@label file modification time", "Modified:"), format.formatRelativeDateTime(modified, QLocale::ShortFormat));
+    }
+
+    addIndexedDetails(item);
+
+    Q_EMIT detailsChanged();
+
+    if (!model->previews()) {
+        return;
+    }
+
+    QStringList plugins = model->effectivePreviewPlugins();
+    if (plugins.isEmpty()) {
+        plugins = KIO::PreviewJob::defaultPlugins();
+    }
+
+    m_previewJob = new KIO::PreviewJob(KFileItemList{item}, QSize(maximumPreviewSize, maximumPreviewSize), &plugins);
+    m_previewJob->setDevicePixelRatio(devicePixelRatio);
+    m_previewJob->setIgnoreMaximumSize(item.isLocalFile() && !item.isSlow());
+
+    connect(m_previewJob, &KIO::PreviewJob::gotPreview, this, [this](const KFileItem &, const QPixmap &pixmap) {
+        m_preview = pixmap.toImage();
+        Q_EMIT previewChanged();
+    });
+}
+
+void ToolTipData::addDetail(const QString &label, const QString &value)
+{
+    if (!value.isEmpty()) {
+        m_details.append(QVariantMap{{QStringLiteral("label"), label}, {QStringLiteral("value"), value}});
+    }
+}
+
+void ToolTipData::addIndexedDetails(const KFileItem &item)
+{
+#ifdef HAVE_BALOO
+    if (!item.isLocalFile() || item.isDir()) {
+        return;
+    }
+
+    Baloo::File file(item.localPath());
+    if (!file.load()) {
+        return;
+    }
+
+    const KFileMetaData::PropertyMultiMap properties = file.properties();
+
+    const QVariant width = properties.value(KFileMetaData::Property::Width);
+    const QVariant height = properties.value(KFileMetaData::Property::Height);
+    if (width.isValid() && height.isValid()) {
+        addDetail(i18nc("@label image dimensions", "Dimensions:"),
+                  i18nc("width × height", "%1 × %2", QString::number(width.toInt()), QString::number(height.toInt())));
+    }
+
+    static const KFileMetaData::Property::Property shownProperties[] = {
+        KFileMetaData::Property::Title,
+        KFileMetaData::Property::Author,
+        KFileMetaData::Property::Artist,
+        KFileMetaData::Property::Album,
+        KFileMetaData::Property::Duration,
+        KFileMetaData::Property::PageCount,
+    };
+
+    for (const auto property : shownProperties) {
+        const QVariant value = properties.value(property);
+        if (value.isValid()) {
+            const KFileMetaData::PropertyInfo info(property);
+            addDetail(i18nc("@label metadata property name followed by its value", "%1:", info.displayName()), info.formatAsDisplayString(value));
+        }
+    }
+#else
+    Q_UNUSED(item)
+#endif
+}
