+}
+
+class ToolTipData : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+
+    Q_PROPERTY(QImage preview READ preview NOTIFY previewChanged)
+    Q_PROPERTY(QSizeF previewSize READ previewSize NOTIFY previewChanged)
+    Q_PROPERTY(QVariantList details READ details NOTIFY detailsChanged)
+
+public:
+    explicit ToolTipData(QObject *parent = nullptr);
+    ~ToolTipData() override;
+
+    QImage preview() const;
+    QSizeF previewSize() const;
+    QVariantList details() const;
+
+    Q_INVOKABLE void load(FolderModel *model, int row, int maximumPreviewSize, qreal devicePixelRatio);
+
+Q_SIGNALS:
+    void previewChanged();
+    void detailsChanged();
+
+private:
+    void addDetail(const QString &label, const QString &value);
+    void addIndexedDetails(const KFileItem &item);
+
+    QImage m_preview;
+    QVariantList m_details;
+    QPointer<KIO::PreviewJob> m_previewJob;
+};
